#include <stdlib.h>
#include <string.h>
#include <float.h>
/* Jonker-Volgenant dense LAP. cost n x n row-major. x[i]=col of row i */
typedef double C;
int lapjv(int n, const C *cost, int *x, int *y, C *u, C *v){
    int *free_rows = malloc(n*sizeof(int));
    int *matches = calloc(n,sizeof(int));
    int *collist = malloc(n*sizeof(int));
    int *pred = malloc(n*sizeof(int));
    C *d = malloc(n*sizeof(C));
    int i,j,j1,j2,k,i0,last,low,up,numfree=0,prv,f,loopcnt;
    C h,u1,u2,mn,umin,usubmin,v2;
    /* column reduction */
    for(j=n-1;j>=0;j--){
        mn=cost[j]; int imin=0;
        for(i=1;i<n;i++){ C c=cost[(size_t)i*n+j]; if(c<mn){mn=c;imin=i;} }
        v[j]=mn;
        if(++matches[imin]==1){ x[imin]=j; y[j]=imin; } else y[j]=-1;
    }
    for(i=0;i<n;i++){
        if(matches[i]==0) free_rows[numfree++]=i;
        else if(matches[i]==1){
            j1=x[i]; mn=DBL_MAX; const C*r=cost+(size_t)i*n;
            for(j=0;j<n;j++) if(j!=j1){ C t=r[j]-v[j]; if(t<mn) mn=t; }
            v[j1]-=mn;
        }
        else x[i]=-1;
    }
    /* augmenting row reduction */
    for(loopcnt=0;loopcnt<2;loopcnt++){
        k=0; prv=numfree; numfree=0;
        while(k<prv){
            i=free_rows[k++]; const C*r=cost+(size_t)i*n;
            u1=r[0]-v[0]; j1=0; u2=DBL_MAX; j2=-1;
            for(j=1;j<n;j++){ h=r[j]-v[j];
                if(h<u2){ if(h>=u1){u2=h;j2=j;} else {u2=u1;u1=h;j2=j1;j1=j;} } }
            i0=y[j1];
            if(u1<u2) v[j1]=v[j1]-(u2-u1);
            else if(i0>=0){ j1=j2; i0=y[j1]; }
            if(i0>=0){ if(u1<u2) free_rows[--k]=i0; else free_rows[numfree++]=i0; }
            x[i]=j1; y[j1]=i;
        }
    }
    /* augmentation */
    for(f=0;f<numfree;f++){
        int freerow=free_rows[f], endofpath=-1;
        const C*r=cost+(size_t)freerow*n;
        for(j=0;j<n;j++){ d[j]=r[j]-v[j]; pred[j]=freerow; collist[j]=n-1-j; }
        low=0; up=0; int unassigned_found=0;
        do{
            if(up==low){
                last=low-1;
                mn=d[collist[up++]];
                for(k=up;k<n;k++){ j=collist[k]; h=d[j];
                    if(h<=mn){ if(h<mn){ up=low; mn=h; } collist[k]=collist[up]; collist[up++]=j; } }
                for(k=low;k<up;k++) if(y[collist[k]]<0){ endofpath=collist[k]; unassigned_found=1; break; }
            }
            if(!unassigned_found){
                j1=collist[low++]; i=y[j1]; const C*ri=cost+(size_t)i*n;
                u1=ri[j1]-v[j1]-mn;
                for(k=up;k<n;k++){ j=collist[k]; v2=ri[j]-v[j]-u1;
                    if(v2<d[j]){ pred[j]=i;
                        if(v2==mn){ if(y[j]<0){ endofpath=j; unassigned_found=1; break; }
                            else { collist[k]=collist[up]; collist[up++]=j; } }
                        d[j]=v2; } }
            }
        } while(!unassigned_found);
        for(k=0;k<=last;k++){ j1=collist[k]; v[j1]+=d[j1]-mn; }
        do{ i=pred[endofpath]; y[endofpath]=i; j1=endofpath; endofpath=x[i]; x[i]=j1; } while(i!=freerow);
    }
    for(i=0;i<n;i++){ j=x[i]; u[i]=cost[(size_t)i*n+j]-v[j]; }
    free(free_rows);free(matches);free(collist);free(pred);free(d);
    return 0;
}
