#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef double C;
/* heap */
typedef struct { C d; int j; } HE;
static void hpush(HE*h,int*sz,C d,int j){ int i=(*sz)++; while(i>0){int p=(i-1)>>1; if(h[p].d<=d) break; h[i]=h[p]; i=p;} h[i].d=d;h[i].j=j; }
static HE hpop(HE*h,int*sz){ HE top=h[0]; HE last=h[--(*sz)]; int n=*sz,i=0; while(1){int c=2*i+1; if(c>=n)break; if(c+1<n&&h[c+1].d<h[c].d)c++; if(h[c].d>=last.d)break; h[i]=h[c]; i=c;} if(n>0)h[i]=last; return top; }

/* returns number of check rounds, or -1 on failure */
int splap(int n, const C *cost, int K, int *x, int *y, C *v){
    int *adj = malloc((size_t)n*n*sizeof(int));
    int *deg = malloc(n*sizeof(int));
    char *full = calloc(n,1);
    char *inset = calloc(n,1);
    int *pred = malloc(n*sizeof(int));
    C *d = malloc(n*sizeof(C));
    int *done = malloc(n*sizeof(int));  /* finalized list */
    int *stamp = calloc(n,sizeof(int)); /* visit stamp */
    char *fin = calloc(n,1);
    HE *heap = malloc(((size_t)n*n+n)*sizeof(HE));
    int *freer = malloc(n*sizeof(int));
    C *tk = malloc((K+1)*sizeof(C)); int *tj = malloc((K+1)*sizeof(int));
    int i,j,k,nf=0,rounds=0;
    if(K>n) K=n;
    /* column min */
    int *amin = malloc(n*sizeof(int));
    for(j=0;j<n;j++){ v[j]=cost[j]; amin[j]=0; }
    for(i=1;i<n;i++){ const C*r=cost+(size_t)i*n; for(j=0;j<n;j++) if(r[j]<v[j]){v[j]=r[j];amin[j]=i;} }
    for(i=0;i<n;i++) x[i]=-1;
    for(j=0;j<n;j++){ y[j]=-1; i=amin[j]; if(x[i]<0){ x[i]=j; y[j]=i; } }
    free(amin);
    /* candidate edges: K smallest reduced cost per row */
    for(i=0;i<n;i++){
        const C*r=cost+(size_t)i*n; int m=0;
        for(j=0;j<n;j++){ C h=r[j]-v[j];
            if(m<K){ int p=m++; while(p>0&&tk[p-1]>h){tk[p]=tk[p-1];tj[p]=tj[p-1];p--;} tk[p]=h;tj[p]=j; }
            else if(h<tk[K-1]){ int p=K-1; while(p>0&&tk[p-1]>h){tk[p]=tk[p-1];tj[p]=tj[p-1];p--;} tk[p]=h;tj[p]=j; } }
        int *a=adj+(size_t)i*n; for(k=0;k<m;k++) a[k]=tj[k];
        deg[i]=m;
        if(x[i]>=0){ int jj=x[i],has=0; for(k=0;k<m;k++) if(a[k]==jj) has=1; if(!has) a[deg[i]++]=jj; }
    }
    for(i=0;i<n;i++) if(x[i]<0) freer[nf++]=i;
    int st=0;
    for(;;){
        for(int f=0;f<nf;f++){
            int fr=freer[f];
        restart:
            st++;
            int hs=0, nd=0, endj=-1; C D=0;
            { const C*r=cost+(size_t)fr*n; int*a=adj+(size_t)fr*n;
              for(k=0;k<deg[fr];k++){ j=a[k]; C h=r[j]-v[j];
                if(stamp[j]!=st||h<d[j]){ stamp[j]=st; fin[j]=0; d[j]=h; pred[j]=fr; hpush(heap,&hs,h,j);} } }
            while(hs>0){
                HE e=hpop(heap,&hs); j=e.j;
                if(fin[j]||e.d>d[j]) continue;
                if(y[j]<0){ endj=j; D=e.d; break; }
                fin[j]=1; done[nd++]=j;
                int ii=y[j]; const C*r=cost+(size_t)ii*n; int*a=adj+(size_t)ii*n;
                C base=e.d-(r[j]-v[j]);
                for(k=0;k<deg[ii];k++){ int jj=a[k]; C h=base+r[jj]-v[jj];
                    if(stamp[jj]!=st){ stamp[jj]=st; fin[jj]=0; d[jj]=h; pred[jj]=ii; hpush(heap,&hs,h,jj);} 
                    else if(!fin[jj]&&h<d[jj]){ d[jj]=h; pred[jj]=ii; hpush(heap,&hs,h,jj);} }
            }
            for(k=0;k<nd;k++){ fin[done[k]]=0; }
            if(endj<0){
                if(full[fr]) goto fail;
                int*a=adj+(size_t)fr*n; for(j=0;j<n;j++) a[j]=j; deg[fr]=n; full[fr]=1;
                goto restart;
            }
            for(k=0;k<nd;k++){ j=done[k]; v[j]+=d[j]-D; }
            j=endj; int ii;
            do{ ii=pred[j]; y[j]=ii; int t=x[ii]; x[ii]=j; j=t; } while(ii!=fr);
        }
        /* check dual feasibility */
        rounds++; nf=0;
        if(rounds>50) goto fail;
        for(i=0;i<n;i++){
            const C*r=cost+(size_t)i*n; int xi=x[i]; C ui=r[xi]-v[xi];
            int bad=0;
            for(j=0;j<n;j++) if(r[j]-v[j]<ui) { bad=1; break; }
            if(bad){
                int*a=adj+(size_t)i*n;
                for(k=0;k<deg[i];k++) inset[a[k]]=1;
                for(j=0;j<n;j++) if(!inset[j] && r[j]-v[j]<ui){ a[deg[i]++]=j; inset[j]=1; }
                for(k=0;k<deg[i];k++) inset[a[k]]=0;
                y[xi]=-1; x[i]=-1; freer[nf++]=i;
            }
        }
        if(nf==0) break;
    }
    free(adj);free(deg);free(full);free(inset);free(pred);free(d);free(done);free(stamp);free(fin);free(heap);free(freer);free(tk);free(tj);
    return rounds;
fail:
    free(adj);free(deg);free(full);free(inset);free(pred);free(d);free(done);free(stamp);free(fin);free(heap);free(freer);free(tk);free(tj);
    return -1;
}
