#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <time.h>
typedef double C;
int stats[8]; double tim[8];
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec*1e6+t.tv_nsec/1e3;}
typedef struct { C d; int j; } HE;
static inline void hpush(HE*h,int*sz,C d,int j){ int i=(*sz)++; while(i>0){int p=(i-1)>>1; if(h[p].d<=d) break; h[i]=h[p]; i=p;} h[i].d=d;h[i].j=j; }
static inline HE hpop(HE*h,int*sz){ HE top=h[0]; HE last=h[--(*sz)]; int n=*sz,i=0; while(1){int c=2*i+1; if(c>=n)break; if(c+1<n&&h[c+1].d<h[c].d)c++; if(h[c].d>=last.d)break; h[i]=h[c]; i=c;} if(n>0)h[i]=last; return top; }

static size_t cap=0; static int *adj; static C *adc; static HE *heap; static char *mk; static C *MT;
static int *deg,*pred,*done,*stamp,*freer,*q; static char *fin,*full; static C *d,*tmp;

/* k-th smallest (0-based) of arr[0..m) via quickselect on copy */
static C kth(C *a, int m, int k){
    int lo=0,hi=m-1;
    while(lo<hi){ C piv=a[(lo+hi)>>1]; int i=lo,j=hi;
        while(i<=j){ while(a[i]<piv)i++; while(a[j]>piv)j--; if(i<=j){C t=a[i];a[i]=a[j];a[j]=t;i++;j--;} }
        if(k<=j) hi=j; else if(k>=i) lo=i; else return a[k]; }
    return a[k];
}
static inline void addedge(int n,int i,int j,C c){ size_t o=(size_t)i*n; if(!mk[o+j]){ mk[o+j]=1; adj[o+deg[i]]=j; adc[o+deg[i]]=c; deg[i]++; } }

int aulap(int n, const C *cost, int K, double eps_final, int *x, int *y, C *v){
    int i,j,k,nf,rounds=0; double t0=now();
    if(cap<(size_t)n*n){ cap=(size_t)n*n; adj=malloc(cap*sizeof(int)); adc=malloc(cap*sizeof(C)); heap=malloc((cap+n)*sizeof(HE)); mk=calloc(cap,1); MT=malloc(cap*sizeof(C));
        deg=malloc(n*sizeof(int)); pred=malloc(n*sizeof(int)); done=malloc(n*sizeof(int)); stamp=calloc(n,sizeof(int)); freer=malloc(n*sizeof(int)); q=malloc(n*sizeof(int));
        fin=calloc(n,1); full=calloc(n,1); d=malloc(n*sizeof(C)); tmp=malloc(n*sizeof(C)); }
    if(K>n) K=n;
    memset(deg,0,n*sizeof(int)); memset(full,0,n);
    /* row candidates */
    for(i=0;i<n;i++){ const C*r=cost+(size_t)i*n; memcpy(tmp,r,n*sizeof(C)); C th=kth(tmp,n,K-1);
        for(j=0;j<n;j++) if(r[j]<=th) addedge(n,i,j,r[j]); }
    /* column candidates via transpose */
    for(int ib=0;ib<n;ib+=32) for(int jb=0;jb<n;jb+=32){ int ie=ib+32<n?ib+32:n, je=jb+32<n?jb+32:n;
        for(i=ib;i<ie;i++) for(j=jb;j<je;j++) MT[(size_t)j*n+i]=cost[(size_t)i*n+j]; }
    for(j=0;j<n;j++){ const C*r=MT+(size_t)j*n; memcpy(tmp,r,n*sizeof(C)); C th=kth(tmp,n,K-1);
        for(i=0;i<n;i++) if(r[i]<=th) addedge(n,i,j,r[i]); }
    tim[0]=now()-t0;
    /* auction, minimization: price p = -v */
    C *p=v; for(j=0;j<n;j++) p[j]=0;
    C cmax=0; for(i=0;i<n;i++){ size_t o=(size_t)i*n; for(k=0;k<deg[i];k++) if(adc[o+k]>cmax) cmax=adc[o+k]; }
    double eps=cmax/8; long iters=0, maxit=(long)n*2000;
